"""Write a KiCad 8 board from a declared list of parts and nets.

Shared by the fixture generators in this directory. It knows about the file
format and nothing else - not about the router, not about which settings win.
That separation is the point: a benchmark generated by code that understands
the thing being measured is not a benchmark.

A part is `(library, reference, value, x, y, pads)` in millimetres relative to
the board origin, and a pad is
`(number, kind, shape, x, y, size_x, size_y, drill, net)` relative to the part.
`drill` is None for surface mount; `net` is None for a pad connected to
nothing.
"""

LAYER_BLOCK = """  (layers
    (0 "F.Cu" signal)
    (31 "B.Cu" signal)
    (32 "B.Adhes" user "B.Adhesive")
    (33 "F.Adhes" user "F.Adhesive")
    (34 "B.Paste" user)
    (35 "F.Paste" user)
    (36 "B.SilkS" user "B.Silkscreen")
    (37 "F.SilkS" user "F.Silkscreen")
    (38 "B.Mask" user)
    (39 "F.Mask" user)
    (40 "Dwgs.User" user "User.Drawings")
    (41 "Cmts.User" user "User.Comments")
    (44 "Edge.Cuts" user)
  )"""


def chip(library, ref, value, x, y, net1, net2, pad_w, pad_h, span, rotate=False):
    """A two-terminal surface-mount part, pads either side of the origin."""
    if rotate:
        offsets = [(0.0, -span / 2), (0.0, span / 2)]
        size = (pad_h, pad_w)
    else:
        offsets = [(-span / 2, 0.0), (span / 2, 0.0)]
        size = (pad_w, pad_h)
    pads = [
        ("1", "smd", "roundrect", offsets[0][0], offsets[0][1], size[0], size[1], None, net1),
        ("2", "smd", "roundrect", offsets[1][0], offsets[1][1], size[0], size[1], None, net2),
    ]
    return (library, ref, value, x, y, pads)


def header(library, ref, value, x, y, nets, pitch=2.54, drill=1.0, pad=1.7):
    """A single-row through-hole header running in +y."""
    pads = [
        (str(i + 1), "thru_hole", "rect" if i == 0 else "oval",
         0.0, i * pitch, pad, pad, drill, net)
        for i, net in enumerate(nets)
    ]
    return (library, ref, value, x, y, pads)


def emit(board_w, board_h, origin_x, origin_y, nets, parts):
    """The whole file, as a string."""
    index = {name: i for i, name in enumerate(nets)}
    out = ['(kicad_pcb (version 20240108) (generator "pcbnew") (generator_version "8.0.0")', ""]
    out += ["  (general", "    (thickness 1.6)", "    (legacy_teardrops no)", "  )", ""]
    out += ['  (paper "A4")', "", LAYER_BLOCK, ""]
    out += ["  (setup", "    (pad_to_mask_clearance 0)",
            "    (allow_soldermask_bridges_in_footprints no)", "  )", ""]
    for name in nets:
        out.append(f'  (net {index[name]} "{name}")')
    out.append("")
    out.append(
        f"  (gr_rect (start {origin_x} {origin_y}) "
        f"(end {origin_x + board_w} {origin_y + board_h}) "
        '(layer "Edge.Cuts") (width 0.05)'
    )
    out += ["    (stroke (width 0.05) (type default))", "  )", ""]

    for library, ref, value, x, y, pads in parts:
        out.append(f'  (footprint "{library}"')
        out.append('    (layer "F.Cu")')
        out.append(f"    (at {origin_x + x:.3f} {origin_y + y:.3f})")
        out.append(f'    (property "Reference" "{ref}")')
        out.append(f'    (property "Value" "{value}")')
        out.append(f'    (property "Footprint" "{library}")')
        for number, kind, shape, px, py, sx, sy, drill, net in pads:
            drill_part = f" (drill {drill})" if drill else ""
            layers = '"*.Cu" "*.Mask"' if kind == "thru_hole" else '"F.Cu" "F.Paste" "F.Mask"'
            net_part = f' (net {index[net]} "{net}")' if net else ""
            out.append(
                f'    (pad "{number}" {kind} {shape} (at {px} {py}) '
                f"(size {sx} {sy}){drill_part} (layers {layers}){net_part})"
            )
        out.append("  )")
        out.append("")

    out.append(")")
    return "\n".join(out) + "\n"


def report(path, parts, nets, board_w, board_h):
    pads = sum(len(p[5]) for p in parts)
    print(f"{path.name}: {len(parts)} parts, {pads} pads, {len(nets) - 1} nets, "
          f"{board_w}x{board_h}mm")
